// @minecraft/server-ui taklidi: formlar sıradaki hazır cevapla kapanır.
export const FormCancelationReason = { UserBusy: "UserBusy", UserClosed: "UserClosed" };
export const answers = []; // her eleman: (form) => yanıt nesnesi
export const shown = [];

function next(form) {
  shown.push(form);
  const fn = answers.shift();
  if (!fn) return { canceled: true, cancelationReason: "UserClosed" };
  return fn(form);
}

export class ActionFormData {
  constructor() { this.kind = "action"; this.buttons = []; this._title = ""; this._body = ""; }
  title(t) { this._title = t; return this; }
  body(b) { this._body = b; return this; }
  button(text, icon) { this.buttons.push({ text, icon }); return this; }
  header() { return this; } label() { return this; } divider() { return this; }
  async show(player) { return next(this); }
}

export class ModalFormData {
  constructor() { this.kind = "modal"; this.fields = []; this._title = ""; }
  title(t) { this._title = t; return this; }
  dropdown(label, items, o = {}) { this.fields.push({ t: "dropdown", label, items, v: o.defaultValueIndex ?? 0 }); return this; }
  slider(label, min, max, o = {}) { this.fields.push({ t: "slider", label, min, max, v: o.defaultValue ?? min }); return this; }
  toggle(label, o = {}) { this.fields.push({ t: "toggle", label, v: !!o.defaultValue }); return this; }
  textField(label, ph, o = {}) { this.fields.push({ t: "text", label, v: o.defaultValue ?? "" }); return this; }
  submitButton() { return this; }
  header() { return this; } label() { return this; } divider() { return this; }
  async show(player) { return next(this); }
}

export class MessageFormData {
  title() { return this; } body() { return this; } button1() { return this; } button2() { return this; }
  async show() { return next(this); }
}

export class ObservableString {
  constructor(d) { this.d = d; }
  getData() { return this.d; }
  setData(d) { this.d = d; }
  subscribe() {} unsubscribe() { return true; }
}
export class ObservableNumber extends ObservableString {}
export class ObservableBoolean extends ObservableString {}

export class CustomForm {
  constructor(player, title) { this.kind = "custom"; this.items = []; this._showing = false; this.title = title; }
  label(t) { this.items.push({ t: "label", v: t }); return this; }
  header(t) { this.items.push({ t: "header", v: t }); return this; }
  button(t, cb) { this.items.push({ t: "button", v: t, cb }); return this; }
  divider() { return this; } spacer() { return this; } closeButton() { return this; }
  image() { return this; } slider() { return this; } toggle() { return this; } dropdown() { return this; } textField() { return this; }
  isShowing() { return this._showing; }
  close() { this._showing = false; }
  async show() {
    this._showing = true;
    shown.push(this);
    const fn = answers.shift();
    if (fn) await fn(this);
    this._showing = false;
    return "ProgrammaticClose";
  }
}
